#[derive(Debug, Clone, PartialEq)]
struct Matrix<T> {
    data: Vec<T>,
    rows: usize,
    cols: usize,
}

impl<T: Clone> Matrix<T> {
    fn new(rows: usize, cols: usize) -> Self {
        Matrix {
            data: Vec::with_capacity(rows * cols),
            rows,
            cols,
        }
    }
    
    fn from_vec(data: Vec<T>, rows: usize, cols: usize) -> Self {
        assert_eq!(data.len(), rows * cols, "Data length must match matrix dimensions");
        Matrix { data, rows, cols }
    }
    
    fn get(&self, row: usize, col: usize) -> &T {
        &self.data[row * self.cols + col]
    }
    
    fn set(&mut self, row: usize, col: usize, value: T) {
        self.data[row * self.cols + col] = value;
    }
}

fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> Matrix<i8> {
    // Extract dimensions from shape
    let r = shape[0] as usize;
    let c = shape[1] as usize;
    
    // Validate assumptions
    assert!(!a.is_empty(), "Input array must have positive length");
    assert_eq!(shape.len(), 2, "Shape array must have length exactly 2");
    assert!(r > 0 && c > 0, "Both shape entries must be positive");
    assert!(
        a.len() == r || a.len() == c,
        "Array length must equal either R or C"
    );
    
    // Create result matrix
    let mut result = Matrix::new(r, c);
    
    if a.len() == r {
        // Treat as column vector: broadcast along columns
        for i in 0..r {
            let element = a[i];
            for j in 0..c {
                result.data.push(element);
            }
        }
    } else {
        // Treat as row vector: broadcast along rows
        for i in 0..r {
            for j in 0..c {
                result.data.push(a[j]);
            }
        }
    }
    
    result
}